          {snapLines.map((line, i) => ( <line key={i} x1={line.x ?? -10000} y1={line.y ?? -10000} x2={line.x ?? 10000} y2={line.y ?? 10000} stroke="#3b82f6" strokeWidth={2/view.scale} strokeDasharray="4 4" /> ))}
