import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';

export interface AssistantConfig {
    onMessage?: (text: string) => void;
    onInterrupted?: () => void;
    onStreamAudio?: (buffer: AudioBuffer, nextTime: number) => void;
}

export class LiveAssistant {
    private ai: any;
    private session: any;
    private audioContext: AudioContext;
    private nextStartTime: number = 0;
    private sources: Set<AudioBufferSourceNode> = new Set();

    constructor() {
        this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    async connect(systemInstruction: string, callbacks: AssistantConfig) {
        this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const sessionPromise = this.ai.live.connect({
            model: 'gemini-2.5-flash-native-audio-preview-12-2025',
            callbacks: {
                onopen: () => console.log('[Assistant] Neural link established.'),
                onmessage: async (message: LiveServerMessage) => {
                    const text = message.serverContent?.modelTurn?.parts?.[0]?.text;
                    if (text) callbacks.onMessage?.(text);

                    const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                    if (base64Audio) {
                        await this.playAudioChunk(base64Audio);
                    }

                    if (message.serverContent?.interrupted) {
                        this.stopAllAudio();
                        callbacks.onInterrupted?.();
                    }
                },
                onerror: (e: any) => console.error('[Assistant] Neural error:', e),
                onclose: () => console.log('[Assistant] Connection closed.')
            },
            config: {
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } }
                },
                systemInstruction
            }
        });

        this.session = await sessionPromise;
        return this.session;
    }

    async sendVoiceInput(float32Data: Float32Array) {
        if (!this.session) return;
        const pcmBlob = this.createPcmBlob(float32Data);
        this.session.sendRealtimeInput({ media: pcmBlob });
    }

    async sendFrame(base64Image: string) {
        if (!this.session) return;
        const data = base64Image.split(',')[1];
        this.session.sendRealtimeInput({
            media: { data, mimeType: 'image/jpeg' }
        });
    }

    private createPcmBlob(data: Float32Array) {
        const int16 = new Int16Array(data.length);
        for (let i = 0; i < data.length; i++) {
            int16[i] = Math.max(-1, Math.min(1, data[i])) * 32768;
        }
        return {
            data: btoa(String.fromCharCode(...new Uint8Array(int16.buffer))),
            mimeType: 'audio/pcm;rate=16000'
        };
    }

    private async playAudioChunk(base64: string) {
        const binary = atob(base64);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);

        const dataInt16 = new Int16Array(bytes.buffer);
        const buffer = this.audioContext.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

        this.nextStartTime = Math.max(this.nextStartTime, this.audioContext.currentTime);
        const source = this.audioContext.createBufferSource();
        source.buffer = buffer;
        source.connect(this.audioContext.destination);
        source.start(this.nextStartTime);
        this.nextStartTime += buffer.duration;
        this.sources.add(source);
        source.onended = () => this.sources.delete(source);
    }

    private stopAllAudio() {
        this.sources.forEach(s => { try { s.stop(); } catch(e) {} });
        this.sources.clear();
        this.nextStartTime = 0;
    }

    close() {
        this.session?.close();
        this.stopAllAudio();
    }
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { 
    MicIcon, StopIcon, XIcon, MessageCircleIcon, 
    SparklesIcon, CameraIcon, BugIcon, FlaskIcon,
    RefreshIcon, PauseIcon, PlayIcon, TargetIcon
} from './Icons';
import { LiveAssistant } from '../services/liveAssistantService';

interface CopilotAssistantProps {
    onCaptureBug: () => Promise<{ image: string, state: any }>;
    onLogInspiration: (text: string) => void;
    canvasSnapshot: () => string | null;
}

const CopilotAssistant: React.FC<CopilotAssistantProps> = ({ onCaptureBug, onLogInspiration, canvasSnapshot }) => {
    const [isActive, setIsActive] = useState(false);
    const [isConnecting, setIsConnecting] = useState(false);
    const [isTalking, setIsTalking] = useState(false);
    const [lastMessage, setLastMessage] = useState<string>('');
    const [isMonitoring, setIsMonitoring] = useState(false);

    const assistantRef = useRef<LiveAssistant>(new LiveAssistant());
    const streamRef = useRef<MediaStream | null>(null);
    const processorRef = useRef<ScriptProcessorNode | null>(null);
    const monitorIntervalRef = useRef<number | null>(null);

    const startVoice = async () => {
        setIsConnecting(true);
        try {
            const systemPrompt = `你是一个工业设计 App 的智能守护助手 (Copilot)。
            你的职责：
            1. 观察用户的无限画布（你会收到截图）。
            2. 协助用户记录 BUG：当用户说“这里坏了”或“记录 BUG”，引导用户指出具体零件。
            3. 记录灵感：将用户的吐槽或创意转录为设计笔记。
            4. 检查一致性：监控引线标注是否对齐。
            语言：简练、专业、有未来感。
            当前 App 状态：3D 模型查看器已就绪，BOM 系统已上线。`;

            await assistantRef.current.connect(systemPrompt, {
                onMessage: (text) => {
                    setLastMessage(text);
                    setIsTalking(true);
                    setTimeout(() => setIsTalking(false), 3000);
                },
                onInterrupted: () => setIsTalking(false)
            });

            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            streamRef.current = stream;

            const audioContext = new AudioContext({ sampleRate: 16000 });
            const source = audioContext.createMediaStreamSource(stream);
            const processor = audioContext.createScriptProcessor(4096, 1, 1);

            processor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                assistantRef.current.sendVoiceInput(inputData);
            };

            source.connect(processor);
            processor.connect(audioContext.destination);
            processorRef.current = processor;

            setIsActive(true);
            setIsMonitoring(true);
        } catch (e) {
            console.error(e);
            alert("无法连接到智脑助理，请检查麦克风权限。");
        } finally {
            setIsConnecting(false);
        }
    };

    const stopVoice = () => {
        assistantRef.current.close();
        processorRef.current?.disconnect();
        streamRef.current?.getTracks().forEach(t => t.stop());
        setIsActive(false);
        setIsMonitoring(false);
    };

    // 视觉监控循环：每 5 秒发送一次画面给 Gemini 保持同步
    useEffect(() => {
        if (isMonitoring) {
            monitorIntervalRef.current = window.setInterval(() => {
                const snap = canvasSnapshot();
                if (snap) assistantRef.current.sendFrame(snap);
            }, 5000);
        } else {
            if (monitorIntervalRef.current) window.clearInterval(monitorIntervalRef.current);
        }
        return () => { if (monitorIntervalRef.current) window.clearInterval(monitorIntervalRef.current); };
    }, [isMonitoring, canvasSnapshot]);

    const handleCapture = async () => {
        const { image, state } = await onCaptureBug();
        // 发送给助理分析
        assistantRef.current.sendFrame(image);
        setLastMessage("正在分析故障点... 已捕获视觉片段。");
    };

    return (
        <div className="fixed bottom-6 right-6 z-[2000] flex flex-col items-end gap-4 pointer-events-none">
            {isActive && (
                <div className="bg-[#0c0c0e]/95 backdrop-blur-3xl border border-white/10 rounded-[28px] p-5 shadow-3xl w-72 flex flex-col gap-4 animate-in slide-in-from-bottom-4 pointer-events-auto">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${isMonitoring ? 'bg-red-500 animate-pulse' : 'bg-zinc-700'}`} />
                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Live Monitoring</span>
                        </div>
                        <XIcon onClick={stopVoice} className="w-4 h-4 text-zinc-600 hover:text-white cursor-pointer" />
                    </div>

                    <div className="flex flex-col gap-3 min-h-[60px] justify-center items-center text-center">
                        {isTalking ? (
                            <div className="flex items-center gap-1">
                                {[1,2,3,4,5].map(i => (
                                    <div key={i} className="w-1 bg-indigo-500 rounded-full animate-wave" style={{ height: '12px', animationDelay: `${i * 0.1}s` }} />
                                ))}
                            </div>
                        ) : (
                            <p className="text-[12px] font-bold text-zinc-300 leading-relaxed italic">
                                {lastMessage || "我在听... 随时向我反馈 BUG 或灵感。"}
                            </p>
                        )}
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                        <button onClick={handleCapture} className="flex items-center justify-center gap-2 py-2.5 bg-zinc-800 hover:bg-red-900/20 text-zinc-400 hover:text-red-400 rounded-xl transition-all border border-white/5">
                            <CameraIcon className="w-4 h-4" />
                            <span className="text-[9px] font-black uppercase">捕获 BUG</span>
                        </button>
                        <button onClick={() => onLogInspiration("用户点击了灵感记录")} className="flex items-center justify-center gap-2 py-2.5 bg-zinc-800 hover:bg-indigo-600/20 text-zinc-400 hover:text-indigo-400 rounded-xl transition-all border border-white/5">
                            <FlaskIcon className="w-4 h-4" />
                            <span className="text-[9px] font-black uppercase">记录灵感</span>
                        </button>
                    </div>
                </div>
            )}

            <button 
                onClick={isActive ? stopVoice : startVoice}
                disabled={isConnecting}
                className={`w-16 h-16 rounded-[24px] flex items-center justify-center shadow-3xl transition-all active:scale-90 pointer-events-auto border-4 ${isActive ? 'bg-[#0c0c0e] border-indigo-600 text-indigo-400' : 'bg-indigo-600 border-[#0c0c0e] text-white hover:scale-110'}`}
            >
                {isConnecting ? (
                    <RefreshIcon className="w-8 h-8 animate-spin" />
                ) : isActive ? (
                    <div className="relative">
                        <div className="absolute inset-0 bg-indigo-500/20 rounded-full animate-ping" />
                        <MessageCircleIcon className="w-8 h-8 relative z-10" />
                    </div>
                ) : (
                    <SparklesIcon className="w-8 h-8" />
                )}
            </button>

            <style>{`
                @keyframes wave {
                    0%, 100% { height: 8px; transform: translateY(0); }
                    50% { height: 24px; transform: translateY(-2px); }
                }
                .animate-wave { animation: wave 1s ease-in-out infinite; }
            `}</style>
        </div>
    );
};

export default CopilotAssistant;

