  // --- 业务逻辑 ---
  const handleUpdateItem = (id: string, updates: Partial<CanvasItem>) => {
      setItems(prev => prev.map(it => it.id === id ? { ...it, ...updates } : it));
      commit(items);
  };

  const handleAddItem = (item: CanvasItem) => {
      setItems(prev => [...prev, item]);
      commit(items);
  };

  const handleDeleteItem = (id: string) => {
      setItems(prev => prev.filter(it => it.id !== id));
      setSelection([]);
      commit(items);
  };

  const captureFullCanvas = useCallback(() => {
      const lastImage = items.find(it => it.type === ItemType.IMAGE && it.content);
      return lastImage?.content || null;
  }, [items]);

  const handleCaptureBug = async () => {
      const lastItem = items[items.length - 1];
      return {
          image: lastItem?.content || '',
          state: {
              itemsCount: items.length,
              selection: selection,
              view: view
          }
      };
  };

  const handleLogInspiration = (text: string) => {
      const spot = findPlacementSpot(240, 100, items);
      const note: CanvasItem = {
          id: crypto.randomUUID(),
          type: ItemType.TEXT,
          x: spot.x, y: spot.y,
          width: 240, height: 100,
          rotation: 0,
          content: `💡 灵感笔记: ${text}\n(由 AI 助理录入)`,
          status: 'generated',
          fontSize: 14,
          textColor: '#6366f1'
      };
      handleAddItem(note);
  };

  const handleGenerate = async (prompt: string, style: string, ratio: string, refs: string[], count: number, artistic: number, resolution: ResolutionType) => {
      const { tasks } = parseGenerationIntent(prompt, null);
      for (const task of tasks) {
          const spot = findPlacementSpot(512, 512, items);
          const newItem: CanvasItem = {
              id: task.nid,
              type: ItemType.IMAGE,
              x: spot.x, y: spot.y,
              width: 512, height: 512,
              rotation: 0,
              content: '',
              status: 'loading',
              prompt: task.prompt
          };
          handleAddItem(newItem);
          try {
              const url = await generateImage(task.prompt, style, ratio, artistic, resolution);
              handleUpdateItem(task.nid, { content: url, status: 'generated' });
              setLastGenerated(url);
          } catch (e) {
              handleUpdateItem(task.nid, { status: 'error' });
          }
      }
  };

  const handleFloatingAction = async (id: string, action: string) => {
      const item = items.find(i => i.id === id);
      if (!item) return;

      if (action === 'delete') handleDeleteItem(id);
      if (action === 'expression') setExpressionState({ itemId: id, isOpen: true });
      if (action === 'inference') setInferenceState({ itemId: id, isOpen: true });
      if (action === 'variation') {
          const url = await generateTopologyVariation(item.content, item.aspectRatio || '1:1', '');
          const spot = findPlacementSpot(item.width, item.height, items, item);
          handleAddItem({ ...item, id: crypto.randomUUID(), x: spot.x, y: spot.y, content: url });
      }
  };

  const handleCloudExport = async () => {
      const pkg: ProjectPackage = { version: '1.0', timestamp: Date.now(), items, view };
      await uploadProjectToCloud(pkg);
  };

  const handleCloudImport = async () => {
      const pkg = await downloadProjectFromCloud();
      setItems(pkg.items);
      setView(pkg.view);
  };

  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative">
      <TopBar 
        onExport={() => {}} 
        onImport={(f) => handleFile(f)} 
        onCloudExport={handleCloudExport}
        onCloudImport={handleCloudImport}
        onNewProject={() => setItems([])}
      />

      <LeftToolbar 
        activeTool={tool} 
        setTool={setTool} 
        onUpload={() => {}}
        onToggleLayers={() => setShowLayers(!showLayers)}
        showLayers={showLayers}
        onToggleHistory={() => setShowHistory(!showHistory)}
        showHistory={showHistory}
        recordingStatus="idle"
        onStartRecording={() => {}}
        onStopRecording={() => {}}
        onPauseRecording={() => {}}
        onResumeRecording={() => {}}
        recordingTime={0}
      />

      <main className="flex-1 relative">
        <Canvas 
          ref={canvasRef} 
          items={items} 
          selection={selection}
          tool={tool}
          view={view}
          setView={setView}
          setSelection={setSelection}
          addItem={handleAddItem}
          updateItem={handleUpdateItem}
          onContextMenu={(e, id) => setContextMenu({ x: e.clientX, y: e.clientY, itemId: id })}
          onDelete={handleDeleteItem}
          expressionState={expressionState}
          setExpressionState={setExpressionState}
          inferenceState={inferenceState}
          setInferenceState={setInferenceState}
          onFloatingAction={handleFloatingAction}
        />

        <div className="absolute right-6 top-6 bottom-32 w-80 pointer-events-none">
           <PropertiesPanel 
             selectedItem={items.find(i => selection.includes(i.id)) || null}
             onUpdateItem={handleUpdateItem}
             onGenerate={() => {}}
             onDelete={handleDeleteItem}
             isCncMode={false}
             setIsCncMode={() => {}}
             onFloatingAction={handleFloatingAction}
           />
        </div>

        <div className="absolute bottom-10 left-1/2 -translate-x-1/2">
            <BottomBar 
                lastGenerated={lastGenerated}
                externalRef={externalRef}
                onExternalRefConsumed={() => setExternalRef(null)}
                onGenerate={handleGenerate}
            />
        </div>
      </main>

      <GeminiChatPanel onAddToCanvas={(b, p) => {
          const spot = findPlacementSpot(512, 512, items);
          handleAddItem({ id: crypto.randomUUID(), type: ItemType.IMAGE, content: b, x: spot.x, y: spot.y, width: 512, height: 512, status: 'generated', prompt: p, rotation: 0 });
      }} />

      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(s) => setItems(s.items)} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection[0] || null} onSelectItem={(id) => setSelection([id])} onUpdateItem={handleUpdateItem} />

      {contextMenu && (
          <ContextMenu 
            x={contextMenu.x} y={contextMenu.y} 
            selectedItem={items.find(i => i.id === contextMenu.itemId) || null} 
            onClose={() => setContextMenu(null)} 
            onSelect={(a) => handleFloatingAction(contextMenu.itemId!, a)}
          />
      )}

      <CopilotAssistant 
        onCaptureBug={handleCaptureBug}
        onLogInspiration={handleLogInspiration}
        canvasSnapshot={captureFullCanvas}
      />
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { 
    MicIcon, StopIcon, XIcon, MessageCircleIcon, 
    SparklesIcon, CameraIcon, BugIcon, FlaskIcon,
    RefreshIcon, PauseIcon, PlayIcon, TargetIcon
} from './Icons';
import { LiveAssistant } from '../services/liveAssistantService';

interface CopilotAssistantProps {
    onCaptureBug: () => Promise<{ image: string, state: any }>;
    onLogInspiration: (text: string) => void;
    canvasSnapshot: () => string | null;
}

const CopilotAssistant: React.FC<CopilotAssistantProps> = ({ onCaptureBug, onLogInspiration, canvasSnapshot }) => {
    const [isActive, setIsActive] = useState(false);
    const [isConnecting, setIsConnecting] = useState(false);
    const [isTalking, setIsTalking] = useState(false);
    const [lastMessage, setLastMessage] = useState<string>('');
    const [isMonitoring, setIsMonitoring] = useState(false);

    const assistantRef = useRef<LiveAssistant>(new LiveAssistant());
    const streamRef = useRef<MediaStream | null>(null);
    const processorRef = useRef<ScriptProcessorNode | null>(null);
    const monitorIntervalRef = useRef<number | null>(null);

    const startVoice = async () => {
        setIsConnecting(true);
        try {
            const systemPrompt = `你是一个工业设计 App 的智能副驾 (Copilot)。
            你的职责：
            1. 观察用户的无限画布（你会收到截图）。
            2. 协助用户记录 BUG：当用户说“这里坏了”或“记录 BUG”，引导用户指出具体零件。
            3. 记录灵感：将用户的吐槽或创意转录为设计笔记。
            4. 检查一致性：监控引线标注是否对齐。
            5. 代码安全：由于你拥有最高权限，请时刻监控 Items 数组是否异常。
            语言：简练、专业、有未来感。`;

            await assistantRef.current.connect(systemPrompt, {
                onMessage: (text) => {
                    setLastMessage(text);
                    setIsTalking(true);
                    setTimeout(() => setIsTalking(false), 3000);
                },
                onInterrupted: () => setIsTalking(false)
            });

            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            streamRef.current = stream;

            const audioContext = new AudioContext({ sampleRate: 16000 });
            const source = audioContext.createMediaStreamSource(stream);
            const processor = audioContext.createScriptProcessor(4096, 1, 1);

            processor.onaudioprocess = (e) => {
                const inputData = e.inputBuffer.getChannelData(0);
                assistantRef.current.sendVoiceInput(inputData);
            };

            source.connect(processor);
            processor.connect(audioContext.destination);
            processorRef.current = processor;

            setIsActive(true);
            setIsMonitoring(true);
        } catch (e) {
            console.error(e);
            alert("无法启动副驾：请检查麦克风权限。");
        } finally {
            setIsConnecting(false);
        }
    };

    const stopVoice = () => {
        assistantRef.current.close();
        processorRef.current?.disconnect();
        streamRef.current?.getTracks().forEach(t => t.stop());
        setIsActive(false);
        setIsMonitoring(false);
    };

    useEffect(() => {
        if (isMonitoring) {
            monitorIntervalRef.current = window.setInterval(() => {
                const snap = canvasSnapshot();
                if (snap) assistantRef.current.sendFrame(snap);
            }, 5000);
        } else {
            if (monitorIntervalRef.current) window.clearInterval(monitorIntervalRef.current);
        }
        return () => { if (monitorIntervalRef.current) window.clearInterval(monitorIntervalRef.current); };
    }, [isMonitoring, canvasSnapshot]);

    const handleCapture = async () => {
        const { image, state } = await onCaptureBug();
        if (image) assistantRef.current.sendFrame(image);
        setLastMessage("正在通过视觉分析链路定位 BUG...");
    };

    return (
        // 关键修改：偏移位置至 right-32 (大约 128px)，避开 Gemini 聊天球
        <div className="fixed bottom-6 right-32 z-[2000] flex flex-col items-end gap-4 pointer-events-none">
            {isActive && (
                <div className="bg-[#0c0c0e]/95 backdrop-blur-3xl border border-white/10 rounded-[28px] p-5 shadow-3xl w-72 flex flex-col gap-4 animate-in slide-in-from-bottom-4 pointer-events-auto origin-bottom-right">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${isMonitoring ? 'bg-red-500 animate-pulse' : 'bg-zinc-700'}`} />
                            <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">System Monitor</span>
                        </div>
                        <XIcon onClick={stopVoice} className="w-4 h-4 text-zinc-600 hover:text-white cursor-pointer" />
                    </div>

                    <div className="flex flex-col gap-3 min-h-[60px] justify-center items-center text-center">
                        {isTalking ? (
                            <div className="flex items-center gap-1">
                                {[1,2,3,4,5].map(i => (
                                    <div key={i} className="w-1 bg-cyan-500 rounded-full animate-wave" style={{ height: '12px', animationDelay: `${i * 0.1}s` }} />
                                ))}
                            </div>
                        ) : (
                            <p className="text-[12px] font-bold text-zinc-300 leading-relaxed italic">
                                {lastMessage || "副驾已就位。正在实时监控画布状态。"}
                            </p>
                        )}
                    </div>

                    <div className="grid grid-cols-2 gap-2">
                        <button onClick={handleCapture} className="flex items-center justify-center gap-2 py-2.5 bg-zinc-800 hover:bg-red-900/20 text-zinc-400 hover:text-red-400 rounded-xl transition-all border border-white/5">
                            <BugIcon className="w-4 h-4" />
                            <span className="text-[9px] font-black uppercase">抓取 BUG</span>
                        </button>
                        <button onClick={() => onLogInspiration("手动触发灵感捕捉")} className="flex items-center justify-center gap-2 py-2.5 bg-zinc-800 hover:bg-indigo-600/20 text-zinc-400 hover:text-indigo-400 rounded-xl transition-all border border-white/5">
                            <FlaskIcon className="w-4 h-4" />
                            <span className="text-[9px] font-black uppercase">速记灵感</span>
                        </button>
                    </div>
                </div>
            )}

            <button 
                onClick={isActive ? stopVoice : startVoice}
                disabled={isConnecting}
                className={`w-14 h-14 rounded-[22px] flex items-center justify-center shadow-3xl transition-all active:scale-90 pointer-events-auto border-4 ${isActive ? 'bg-[#0c0c0e] border-cyan-600 text-cyan-400 shadow-[0_0_20px_rgba(6,182,212,0.3)]' : 'bg-cyan-600 border-[#0c0c0e] text-white hover:scale-110'}`}
                title="Industrial Copilot (副驾助手)"
            >
                {isConnecting ? (
                    <RefreshIcon className="w-6 h-6 animate-spin" />
                ) : isActive ? (
                    <div className="relative">
                        <TargetIcon className="w-7 h-7 relative z-10" />
                    </div>
                ) : (
                    <ZapIcon className="w-7 h-7" />
                )}
            </button>

            <style>{`
                @keyframes wave {
                    0%, 100% { height: 8px; transform: translateY(0); }
                    50% { height: 20px; transform: translateY(-1px); }
                }
                .animate-wave { animation: wave 0.8s ease-in-out infinite; }
            `}</style>
        </div>
    );
};

export default CopilotAssistant;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { 
  CanvasItem, ItemType, ViewState, ToolType, EditToolType, 
  ResolutionType, ProjectPackage 
} from './types';
import Canvas, { CanvasRef } from './components/Canvas';
import LeftToolbar from './components/LeftToolbar';
import TopBar from './components/TopBar';
import BottomBar from './components/BottomBar';
import PropertiesPanel from './components/PropertiesPanel';
import GeminiChatPanel from './components/GeminiChatPanel';
import HistoryPanel from './components/HistoryPanel';
import LayersPanel from './components/LayersPanel';
import ContextMenu from './components/ContextMenu';
import CopilotAssistant from './components/CopilotAssistant';
import { useAssetManager } from './hooks/useAssetManager';
import { useHistory } from './hooks/useHistory';
import { useProjectPersistence } from './hooks/useProjectPersistence';
import { uploadProjectToCloud, downloadProjectFromCloud } from './services/firebaseService';
import { parseGenerationIntent } from './services/intentParser';
import { generateImage, generateTopologyVariation, generateBOMData, parseModelSemanticCommand } from './services/geminiService';

const App: React.FC = () => {
  // --- 核心画布状态 ---
  const [items, setItems] = useState<CanvasItem[]>([]);
  const [selection, setSelection] = useState<string[]>([]);
  const [view, setView] = useState<ViewState>({ x: 0, y: 0, scale: 1 });
  const [tool, setTool] = useState<ToolType>('select');

  // --- UI 显隐状态 ---
  const [showLayers, setShowLayers] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [lastGenerated, setLastGenerated] = useState<string | null>(null);
  const [externalRef, setExternalRef] = useState<string | null>(null);
  const [isPickingPoint, setIsPickingPoint] = useState(false);

  // --- 交互助手相关 ---
  const [contextMenu, setContextMenu] = useState<{ x: number, y: number, itemId?: string } | null>(null);
  const [expressionState, setExpressionState] = useState({ itemId: '', isOpen: false });
  const [inferenceState, setInferenceState] = useState({ itemId: '', isOpen: false });
  const [activePartId, setActivePartId] = useState<string>('');

  const canvasRef = useRef<CanvasRef>(null);
  const prevItemsCount = useRef(0);

  // --- Hooks 集成 ---
  const { commit, undo, redo, canUndo, canRedo } = useHistory(items);
  const { findPlacementSpot, handleFile } = useAssetManager({ view, items, setItems, setSelection });
  useProjectPersistence(items, (loaded) => {
      setItems(loaded);
      prevItemsCount.current = loaded.length;
  });

  // --- 回归监控 (Regression Watchdog) ---
  useEffect(() => {
      if (prevItemsCount.current > 3 && items.length < prevItemsCount.current * 0.5) {
          console.error("[RegWatch] 检测到大规模元素丢失！可能存在误删逻辑。");
      }
      prevItemsCount.current = items.length;
  }, [items]);

  // --- 业务操作集 ---
  const handleUpdateItem = useCallback((id: string, updates: Partial<CanvasItem>) => {
      setItems(prev => prev.map(it => it.id === id ? { ...it, ...updates } : it));
      // 注意：这里不立即 commit，由具体的交互动作决定何时记录历史
  }, []);

  const handleAddItem = useCallback((item: CanvasItem) => {
      setItems(prev => [...prev, item]);
      commit([...items, item]);
  }, [items, commit]);

  const handleDeleteItem = useCallback((id: string) => {
      setItems(prev => prev.filter(it => it.id !== id));
      setSelection([]);
      commit(items.filter(it => it.id !== id));
  }, [items, commit]);

  // --- Copilot 视觉接口 ---
  const captureFullCanvas = useCallback(() => {
      const lastImg = items.find(it => it.type === ItemType.IMAGE && it.content);
      return lastImg?.content || null;
  }, [items]);

  const handleCaptureBug = async () => {
      const selected = items.find(i => selection.includes(i.id));
      return {
          image: selected?.content || captureFullCanvas() || '',
          state: {
              itemsCount: items.length,
              selection: selection,
              lastAction: "Bug Capture"
          }
      };
  };

  const handleLogInspiration = (text: string) => {
      const spot = findPlacementSpot(280, 120, items);
      const note: CanvasItem = {
          id: crypto.randomUUID(),
          type: ItemType.TEXT,
          x: spot.x, y: spot.y,
          width: 280, height: 120,
          rotation: 0,
          content: `📝 灵感闪现: ${text}\n(由副驾实时录入)`,
          status: 'generated',
          fontSize: 16,
          textColor: '#0ea5e9'
      };
      handleAddItem(note);
  };

  // --- AI 生成分发 ---
  const handleGenerate = async (prompt: string, style: string, ratio: string) => {
      const { tasks } = parseGenerationIntent(prompt, null);
      for (const task of tasks) {
          const spot = findPlacementSpot(512, 512, items);
          const nid = task.nid;
          const newItem: CanvasItem = {
              id: nid,
              type: ItemType.IMAGE,
              x: spot.x, y: spot.y,
              width: 512, height: 512,
              rotation: 0,
              content: '',
              status: 'loading',
              prompt: task.prompt
          };
          handleAddItem(newItem);
          try {
              const url = await generateImage(task.prompt, style, ratio);
              handleUpdateItem(nid, { content: url, status: 'generated' });
              setLastGenerated(url);
          } catch (e) {
              handleUpdateItem(nid, { status: 'error' });
          }
      }
  };

  const handleFloatingAction = async (id: string, action: string) => {
      const item = items.find(i => i.id === id);
      if (!item) return;

      if (action === 'delete') handleDeleteItem(id);
      if (action === 'expression') setExpressionState({ itemId: id, isOpen: true });
      if (action === 'inference') setInferenceState({ itemId: id, isOpen: true });

      // 特殊：3D 语义指令
      if (action.startsWith('model_cmd:')) {
          const cmd = action.replace('model_cmd:', '');
          const result = await parseModelSemanticCommand(cmd, item.partList || []);
          if (result.action === 'paint' && result.params.color) {
              const currentCMF = item.partCMFMap || {};
              const nextCMF = { ...currentCMF };
              result.targets.forEach((t: string) => {
                  nextCMF[t] = { color: result.params.color, metalness: result.params.metalness, roughness: result.params.roughness };
              });
              handleUpdateItem(id, { partCMFMap: nextCMF });
          } else if (result.action === 'explode') {
              handleUpdateItem(id, { explodeFactor: result.params.explodeFactor });
          }
      }

      // 特殊：生成 BOM
      if (action === 'generate_bom') {
          const bomData = await generateBOMData(item.partList || []);
          const spot = findPlacementSpot(600, 400, items, item);
          const bomTable: CanvasItem = {
              id: crypto.randomUUID(),
              type: ItemType.TEXT,
              x: spot.x, y: spot.y,
              width: 640, height: 480,
              rotation: 0,
              content: JSON.stringify(bomData),
              status: 'generated',
              links: [item.id]
          };
          handleAddItem(bomTable);
      }
  };

  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative">
      <TopBar 
        onExport={() => {}} 
        onImport={(f) => handleFile(f)} 
        onCloudExport={async () => await uploadProjectToCloud({ items, view, timestamp: Date.now(), version: '1.0' })}
        onCloudImport={async () => { const p = await downloadProjectFromCloud(); setItems(p.items); setView(p.view); }}
        onNewProject={() => setItems([])}
      />

      <LeftToolbar 
        activeTool={tool} 
        setTool={setTool} 
        onUpload={() => {}}
        onToggleLayers={() => setShowLayers(!showLayers)}
        showLayers={showLayers}
        onToggleHistory={() => setShowHistory(!showHistory)}
        showHistory={showHistory}
        recordingStatus="idle"
        onStartRecording={() => {}}
        onStopRecording={() => {}}
        onPauseRecording={() => {}}
        onResumeRecording={() => {}}
        recordingTime={0}
      />

      <main className="flex-1 relative">
        <Canvas 
          ref={canvasRef} 
          items={items} 
          selection={selection}
          tool={tool}
          view={view}
          setView={setView}
          setSelection={setSelection}
          addItem={handleAddItem}
          updateItem={handleUpdateItem}
          onContextMenu={(e, id) => setContextMenu({ x: e.clientX, y: e.clientY, itemId: id })}
          onDelete={handleDeleteItem}
          expressionState={expressionState}
          setExpressionState={setExpressionState}
          inferenceState={inferenceState}
          setInferenceState={setInferenceState}
          activePartId={activePartId}
          onPartSelect={setActivePartId}
          onFloatingAction={handleFloatingAction}
          onLoadParts={(id, parts) => handleUpdateItem(id, { partList: parts })}
        />

        <div className="absolute right-6 top-6 bottom-32 w-80 pointer-events-none">
           <PropertiesPanel 
             selectedItem={items.find(i => selection.includes(i.id)) || null}
             onUpdateItem={handleUpdateItem}
             onGenerate={() => {}}
             onDelete={handleDeleteItem}
             isCncMode={false}
             setIsCncMode={() => {}}
             onFloatingAction={handleFloatingAction}
             onClosePanel={() => setSelection([])}
           />
        </div>

        <div className="absolute bottom-10 left-1/2 -translate-x-1/2">
            <BottomBar 
                lastGenerated={lastGenerated}
                externalRef={externalRef}
                onExternalRefConsumed={() => setExternalRef(null)}
                onGenerate={handleGenerate}
            />
        </div>
      </main>

      {/* 右下角工具组 */}
      <div className="fixed bottom-6 right-6 z-[60] flex items-center gap-4 pointer-events-none">
          {/* 副驾球 (由组件内部处理位置，此处为逻辑对齐) */}
          <CopilotAssistant 
            onCaptureBug={handleCaptureBug}
            onLogInspiration={handleLogInspiration}
            canvasSnapshot={captureFullCanvas}
          />

          {/* Gemini 创作中心 */}
          <div className="pointer-events-auto">
            <GeminiChatPanel onAddToCanvas={(b, p) => {
                const spot = findPlacementSpot(512, 512, items);
                handleAddItem({ id: crypto.randomUUID(), type: ItemType.IMAGE, content: b, x: spot.x, y: spot.y, width: 512, height: 512, status: 'generated', prompt: p, rotation: 0 });
            }} />
          </div>
      </div>

