import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';

export interface AssistantConfig {
    onMessage?: (text: string) => void;
    onInterrupted?: () => void;
    onStreamAudio?: (buffer: AudioBuffer, nextTime: number) => void;
}

export class LiveAssistant {
    private ai: any;
    private session: any;
    private audioContext: AudioContext;
    private nextStartTime: number = 0;
    private sources: Set<AudioBufferSourceNode> = new Set();
    public isMicAvailable: boolean = false;

    constructor() {
        this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    async connect(systemInstruction: string, callbacks: AssistantConfig) {
        this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        const sessionPromise = this.ai.live.connect({
            model: 'gemini-2.5-flash-native-audio-preview-12-2025',
            callbacks: {
                onopen: () => console.log('[Assistant] 视觉/语义链路已就绪'),
                onmessage: async (message: LiveServerMessage) => {
                    const text = message.serverContent?.modelTurn?.parts?.[0]?.text;
                    if (text) callbacks.onMessage?.(text);

                    const base64Audio = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                    if (base64Audio) {
                        await this.playAudioChunk(base64Audio);
                    }

                    if (message.serverContent?.interrupted) {
                        this.stopAllAudio();
                        callbacks.onInterrupted?.();
                    }
                },
                onerror: (e: any) => console.error('[Assistant] 会话异常:', e),
                onclose: () => console.log('[Assistant] 会话已断开')
            },
            config: {
                // 如果没有麦克风，我们依然保持 AUDIO 模态，以便接收 AI 的语音反馈
                responseModalities: [Modality.AUDIO],
                speechConfig: {
                    voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } }
                },
                systemInstruction
            }
        });

        this.session = await sessionPromise;
        return this.session;
    }

    async sendVoiceInput(float32Data: Float32Array) {
        if (!this.session) return;
        try {
            const pcmBlob = this.createPcmBlob(float32Data);
            this.session.sendRealtimeInput({ media: pcmBlob });
        } catch (e) {
            // 吞掉语音发送错误，不影响视觉发送
        }
    }

    async sendFrame(base64Image: string) {
        if (!this.session) return;
        try {
            const data = base64Image.split(',')[1] || base64Image;
            this.session.sendRealtimeInput({
                media: { data, mimeType: 'image/jpeg' }
            });
        } catch (e) {
            console.warn("[Assistant] 视觉帧发送失败", e);
        }
    }

    private createPcmBlob(data: Float32Array) {
        const int16 = new Int16Array(data.length);
        for (let i = 0; i < data.length; i++) {
            int16[i] = Math.max(-1, Math.min(1, data[i])) * 32768;
        }
        return {
            data: btoa(String.fromCharCode(...new Uint8Array(int16.buffer))),
            mimeType: 'audio/pcm;rate=16000'
        };
    }

    private async playAudioChunk(base64: string) {
        try {
            const binary = atob(base64);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);

            const dataInt16 = new Int16Array(bytes.buffer);
            const buffer = this.audioContext.createBuffer(1, dataInt16.length, 24000);
            const channelData = buffer.getChannelData(0);
            for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;

            this.nextStartTime = Math.max(this.nextStartTime, this.audioContext.currentTime);
            const source = this.audioContext.createBufferSource();
            source.buffer = buffer;
            source.connect(this.audioContext.destination);
            source.start(this.nextStartTime);
            this.nextStartTime += buffer.duration;
            this.sources.add(source);
            source.onended = () => this.sources.delete(source);
        } catch (e) {
            console.error("[Assistant] 播放语音失败", e);
        }
    }

    private stopAllAudio() {
        this.sources.forEach(s => { try { s.stop(); } catch(e) {} });
        this.sources.clear();
        this.nextStartTime = 0;
    }

    close() {
        this.session?.close();
        this.stopAllAudio();
    }
}

