  const [showLayers, setShowLayers] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [lastGenerated, setLastGenerated] = useState<string | null>(null);
  const [activePartId, setActivePartId] = useState<string>('');
  const [contextMenu, setContextMenu] = useState<{ x: number, y: number, itemId?: string } | null>(null);
  const [expressionState, setExpressionState] = useState({ itemId: '', isOpen: false });
  const [inferenceState, setInferenceState] = useState({ itemId: '', isOpen: false });

  const canvasRef = useRef<CanvasRef>(null);
  const prevItemsCount = useRef(0);

  // --- Hooks ---
  const { commit, undo, redo } = useHistory(items);
