    const handleKeyDown = (e: KeyboardEvent) => {
        if (['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName)) return;

        if (e.key === 'v' || e.key === 'V') setTool('select');
        if (e.key === 'h' || e.key === 'H') setTool('hand');
        if (e.key === 'z' && (e.metaKey || e.ctrlKey)) { e.preventDefault(); undo(); }
        if (e.key === 'Delete' || e.key === 'Backspace') { selection.forEach(id => handleDeleteItem(id)); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selection, undo]);

  // --- 导航功能逻辑 ---
  const handleZoom = (delta: number) => {
      setView(v => ({ ...v, scale: Math.min(Math.max(v.scale * delta, 0.05), 10) }));
  };

  const handleResetView = () => setView({ x: 0, y: 0, scale: 1 });

  // --- 业务逻辑 ---
  const handleUpdateItem = useCallback((id: string, updates: Partial<CanvasItem>) => {
      setItems(prev => prev.map(it => it.id === id ? { ...it, ...updates } : it));
  }, []);

  const handleAddItem = useCallback((item: CanvasItem) => {
      setItems(prev => [...prev, item]);
      commit([...items, item]);
  }, [items, commit]);

  const handleDeleteItem = useCallback((id: string) => {
      setItems(prev => prev.filter(it => it.id !== id));
      setSelection([]);
      commit(items.filter(it => it.id !== id));
  }, [items, commit]);

  const captureFullCanvas = useCallback(() => {
      const lastImg = items.find(it => it.type === ItemType.IMAGE && it.content);
      return lastImg?.content || null;
  }, [items]);

  const handleGenerate = async (prompt: string, style: string, ratio: string) => {
      const { tasks } = parseGenerationIntent(prompt, null);
      for (const task of tasks) {
          const spot = findPlacementSpot(512, 512, items);
          const nid = task.nid;
          handleAddItem({ id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: 512, height: 512, rotation: 0, content: '', status: 'loading', prompt: task.prompt });
          try {
              const url = await generateImage(task.prompt, style, ratio);
