      if (action === 'delete') handleDeleteItem(id);
      if (action === 'expression') setExpressionState({ itemId: id, isOpen: true });
      if (action === 'inference') setInferenceState({ itemId: id, isOpen: true });
  };

  // --- Copilot Assistant Handlers (Fix for missing handlers) ---
  /**
   * 捕获画布当前的视觉数据及其逻辑状态，供副驾进行语义审计
   */
  const handleCaptureBug = useCallback(async () => {
    const img = captureFullCanvas();
    return { 
        image: img || '', 
        state: { 
            totalItems: items.length, 
            scale: view.scale,
            canvasCenter: { x: view.x, y: view.y }
        } 
    };
  }, [captureFullCanvas, items, view]);

