   * 将用户的灵感或吐槽由副驾转录为画布上的“灵感贴纸”
   */
  const handleLogInspiration = useCallback((text: string) => {
    const spot = findPlacementSpot(260, 100, items);
    handleAddItem({
        id: crypto.randomUUID(),
        type: ItemType.TEXT,
        x: spot.x,
        y: spot.y,
        width: 260,
        height: 100,
        rotation: 0,
        content: `💡 副驾录入灵感:\n${text}`,
        status: 'generated',
        fontSize: 16,
        fontWeight: '900',
        textColor: '#6366f1'
    });
  }, [items, findPlacementSpot, handleAddItem]);

  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative">
      <TopBar 
        onExport={() => {}} 
        onImport={(f) => handleFile(f)} 
        onCloudExport={async () => await uploadProjectToCloud({ items, view, timestamp: Date.now(), version: '1.0' })}
        onCloudImport={async () => { const p = await downloadProjectFromCloud(); setItems(p.items); setView(p.view); }}
        onNewProject={() => setItems([])}
      />

      <LeftToolbar 
        activeTool={tool} setTool={setTool} 
        onUpload={() => {}} 
        onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers}
        onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory}
        recordingStatus="idle" onStartRecording={() => {}} onStopRecording={() => {}} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={0}
      />

      <main className="flex-1 relative">
        <Canvas 
          ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection}
          addItem={handleAddItem} updateItem={handleUpdateItem} onDelete={handleDeleteItem}
          onContextMenu={(e, id) => setContextMenu({ x: e.clientX, y: e.clientY, itemId: id })}
          expressionState={expressionState} setExpressionState={setExpressionState}
          inferenceState={inferenceState} setInferenceState={setInferenceState}
          activePartId={activePartId} onPartSelect={setActivePartId} onFloatingAction={handleFloatingAction}
          onLoadParts={(id, parts) => handleUpdateItem(id, { partList: parts })}
        />

        {/* 属性面板区域 */}
        <div className="absolute right-6 top-6 bottom-32 w-80 pointer-events-none">
           <PropertiesPanel 
             selectedItem={items.find(i => selection.includes(i.id)) || null}
             onUpdateItem={handleUpdateItem} onGenerate={() => {}} onDelete={handleDeleteItem}
             isCncMode={false} setIsCncMode={() => {}} onFloatingAction={handleFloatingAction}
             onClosePanel={() => setSelection([])}
           />
        </div>

        {/* 底部生成栏 */}
        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-50">
            <BottomBar lastGenerated={lastGenerated} externalRef={null} onExternalRefConsumed={() => {}} onGenerate={handleGenerate} />
