            </div>

            {/* 2. 智能副驾：按需审计版 */}
            <div className="pointer-events-auto">
                <CopilotAssistant 
                    onCaptureBug={async () => ({ image: captureFullCanvas() || '', state: { itemsCount: items.length } })} 
                    onLogInspiration={() => {}} 
                    canvasSnapshot={captureFullCanvas}
                    items={items} 
                />
            </div>

            {/* 3. Gemini 聊天球 */}
            <div className="pointer-events-auto">
                <GeminiChatPanel onAddToCanvas={(b, p) => {
                    const spot = findPlacementSpot(512, 512, items);
                    handleAddItem({ id: crypto.randomUUID(), type: ItemType.IMAGE, content: b, x: spot.x, y: spot.y, width: 512, height: 512, status: 'generated', prompt: p, rotation: 0 });
                }} />
            </div>
        </div>
      </main>

      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(s) => { setItems(s.items); setShowHistory(false); }} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection[0] || null} onSelectItem={(id) => setSelection([id])} onUpdateItem={handleUpdateItem} />

      {contextMenu && (
          <ContextMenu 
            x={contextMenu.x} y={contextMenu.y} 
            selectedItem={items.find(i => i.id === contextMenu.itemId) || null} 
            onClose={() => setContextMenu(null)} 
            onSelect={(a) => { handleFloatingAction(contextMenu.itemId!, a); setContextMenu(null); }}
          />
      )}
    </div>
  );
};

