import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';

export interface AssistantCallbacks {
    onMessage?: (text: string) => void;
    onInterrupted?: () => void;
    onError?: (error: any) => void;
}

export class LiveAssistant {
    private ai: any;
    private session: any | null = null;
    private sessionPromise: Promise<any> | null = null;

    constructor() {
        this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    }

    async connect(systemInstruction: string, callbacks: AssistantCallbacks) {
        if (this.session) await this.close();

        this.sessionPromise = this.ai.live.connect({
            model: 'gemini-2.5-flash-native-audio-preview-12-2025',
            config: {
                responseModalities: [Modality.AUDIO],
                systemInstruction,
                outputAudioTranscription: {},
            },
            callbacks: {
                onopen: () => {
                    console.debug('Live Auditor Session Opened');
                },
                onmessage: async (message: LiveServerMessage) => {
                    if (message.serverContent?.outputTranscription) {
                        callbacks.onMessage?.(message.serverContent.outputTranscription.text);
                    }
                    if (message.serverContent?.interrupted) {
                        callbacks.onInterrupted?.();
                    }
                },
                onerror: (e: any) => {
                    console.error('Live Auditor Error:', e);
                    callbacks.onError?.(e);
                },
                onclose: () => {
                    console.debug('Live Auditor Session Closed');
                    this.session = null;
                }
            }
        });

        this.session = await this.sessionPromise;
        return this.session;
    }

    async sendFrame(base64Image: string) {
        if (!this.sessionPromise) return;

        // Remove mime prefix if present
        const data = base64Image.includes('base64,') 
            ? base64Image.split('base64,')[1] 
            : base64Image;

        this.sessionPromise.then((session) => {
            session.sendRealtimeInput({
                media: {
                    data: data,
                    mimeType: 'image/jpeg'
                }
            });
        });
    }

    async close() {
        if (this.session) {
            this.session.close();
            this.session = null;
            this.sessionPromise = null;
        }
    }
}

// Internal helper for manual base64 encoding if needed by other modules
export function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

// Internal helper for manual base64 decoding
export function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

