            setLastMessage("副驾已就绪。建议先【标记基准版本】，以便我在您更新代码后执行对比审计。");
        } catch (e) {
            console.error(e);
            alert("审计链路连接失败。");
        } finally {
            setIsConnecting(false);
        }
    };

    const stopAssistant = () => {
        assistantRef.current.close();
        setIsActive(false);
        setIsAuditing(false);
    };

    const handleMarkBaseline = () => {
        setBaselineItems(JSON.stringify(items.map(i => ({ id: i.id, type: i.type, pos: [i.x, i.y], parts: i.partList?.length }))));
        setBaselineTS(Date.now());
        setLastMessage(`✅ 已成功标记基准版本 (${items.length} 个对象)。现在您可以放心去修改程序了。`);
    };

    const handleRunAudit = async () => {
        if (!isActive) return;
        setIsAuditing(true);
        setLastMessage("正在抓取视觉帧并对比逻辑树，请稍候...");

        const snap = canvasSnapshot();
        const currentState = JSON.stringify(items.map(i => ({ id: i.id, type: i.type, pos: [i.x, i.y], parts: i.partList?.length })));

        if (snap) {
            // Send the visual context
            await assistantRef.current.sendFrame(snap);
            // In a real Live API session, we would speak or send a text part to prompt the analysis.
            // Since we're simulating the audit feedback loop:
            console.debug('Auditing with state:', currentState);
        }

        // Simulate analysis duration
        setTimeout(() => setIsAuditing(false), 2000);
    };

    return (
        <div className="relative flex flex-col items-end gap-4 pointer-events-none">
            {isActive && (
                <div className="absolute bottom-[80px] right-0 bg-[#0c0c0e]/95 backdrop-blur-3xl border border-white/10 rounded-[32px] p-6 shadow-3xl w-80 flex flex-col gap-5 animate-in slide-in-from-bottom-4 pointer-events-auto">
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-2">
                            <div className={`w-2 h-2 rounded-full ${isAuditing ? 'bg-orange-500 animate-ping' : 'bg-emerald-500'}`} />
                            <span className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">Logic Auditor</span>
                        </div>
                        <XIcon onClick={stopAssistant} className="w-4 h-4 text-zinc-600 hover:text-white cursor-pointer" />
                    </div>

                    <div className="bg-white/5 rounded-2xl p-4 min-h-[80px] flex flex-col justify-center border border-white/5">
                        <p className="text-[12px] font-bold text-zinc-300 leading-relaxed italic">
                            {lastMessage}
                        </p>
                    </div>

                    <div className="grid grid-cols-1 gap-2">
                        <button 
                            onClick={handleMarkBaseline} 
                            className="flex items-center justify-between px-4 py-3 bg-zinc-800 hover:bg-zinc-700 text-zinc-300 rounded-xl transition-all border border-white/5 group"
                        >
                            <div className="flex items-center gap-3">
                                <CheckIcon className="w-4 h-4 text-emerald-400" />
                                <span className="text-[11px] font-black uppercase">标记健康基准</span>
                            </div>
                            <span className="text-[9px] font-mono text-zinc-600">v1.0</span>
                        </button>

                        <button 
                            onClick={handleRunAudit}
                            disabled={isAuditing}
                            className={`flex items-center justify-between px-4 py-4 rounded-xl transition-all border shadow-xl active:scale-95 ${isAuditing ? 'bg-orange-600/20 border-orange-500 text-orange-400' : 'bg-indigo-600 hover:bg-indigo-500 border-indigo-400 text-white'}`}
                        >
                            <div className="flex items-center gap-3">
                                {isAuditing ? <RefreshIcon className="w-5 h-5 animate-spin" /> : <BugIcon className="w-5 h-5" />}
                                <span className="text-[12px] font-black uppercase tracking-widest">执行程序审计</span>
                            </div>
                            <ZapIcon className="w-4 h-4 opacity-50" />
                        </button>
                    </div>

                    {baselineTS && (
                        <div className="flex items-center gap-2 px-2">
                            <ClockIcon className="w-3 h-3 text-zinc-700" />
                            <span className="text-[9px] font-bold text-zinc-600 uppercase">上次快照: {new Date(baselineTS).toLocaleTimeString()}</span>
                        </div>
                    )}
                </div>
            )}

            <button 
                onClick={isActive ? stopAssistant : startAssistant}
                disabled={isConnecting}
                className={`w-14 h-14 rounded-[22px] flex items-center justify-center shadow-3xl transition-all active:scale-90 pointer-events-auto border-4 ${isActive ? 'bg-[#0c0c0e] border-indigo-600 text-indigo-400 ring-4 ring-indigo-500/20' : 'bg-zinc-900 border-zinc-800 text-zinc-500 hover:text-white hover:border-zinc-700'}`}
                title="Industrial Copilot"
            >
                {isConnecting ? (
                    <RefreshIcon className="w-6 h-6 animate-spin" />
                ) : (
                    <TargetIcon className="w-8 h-8" />
                )}
            </button>
        </div>
    );
};

export default CopilotAssistant;
